[{"order":1,"type":"heading","text":"PHP Namespaces: Organizing Your Code"},{"order":2,"type":"paragraph","text":"Namespaces in PHP provide a way to encapsulate and organize code, preventing naming conflicts between classes, interfaces, functions, and constants. They act as containers, allowing you to group related code under a unique identifier."},{"order":3,"type":"subheading","text":"Declaring a Namespace"},{"order":4,"type":"paragraph","text":"A namespace is declared using the 'namespace' keyword at the beginning of a PHP file. It's best practice to declare the namespace at the very top of the file, before any other PHP code (except for a declare statement for things like strict_types)."},{"order":5,"type":"code","text":"<?php
namespace MyProject\MyModule;

// Code within this namespace
?>"},{"order":6,"type":"paragraph","text":"In the example above, we've declared a namespace called 'MyProject\MyModule'. Note the use of backslashes ('\') to separate namespace levels. This is the recommended way to structure namespaces."},{"order":7,"type":"subheading","text":"Using Namespaces"},{"order":8,"type":"paragraph","text":"To use elements (classes, functions, etc.) from a namespace, you have several options:"},{"order":9,"type":"bullet_point","text":"Fully Qualified Names: Refer to the element using its complete namespace path (e.g., 'MyProject\MyModule\MyClass')."},{"order":10,"type":"bullet_point","text":"The 'use' Keyword: Import the namespace or specific elements into the current scope using the 'use' keyword. This allows you to refer to them using shorter, unqualified names."},{"order":11,"type":"subheading","text":"Examples of Using Namespaces"},{"order":12,"type":"code","text":"<?php
namespace MyProject\MyModule;

class MyClass {
 public function __construct() {
 echo "MyClass from MyProject\\MyModule";
 }
}

function myFunction() {
 echo "myFunction from MyProject\\MyModule";
}

const MY_CONSTANT = "My Constant Value";

?>"},{"order":13,"type":"code","text":"<?php
// Using the fully qualified name
$obj = new MyProject\MyModule\MyClass();

MyProject\MyModule\myFunction();

echo MyProject\MyModule\MY_CONSTANT;

// Using the 'use' keyword to import the class
use MyProject\MyModule\MyClass;

$obj2 = new MyClass();

// Using the 'use' keyword to import the function
use MyProject\MyModule\myFunction;

myFunction();

// Using the 'use' keyword to import the constant
use MyProject\MyModule\MY_CONSTANT;

echo MY_CONSTANT;

// Using the 'use' keyword to import the entire namespace
use MyProject\MyModule;

$obj3 = new MyModule\MyClass();
MyModule\myFunction();
echo MyModule\MY_CONSTANT;

?>"},{"order":14,"type":"subheading","text":"Sub-namespaces"},{"order":15,"type":"paragraph","text":"Namespaces can be nested to create a hierarchy. This is done by using multiple levels separated by backslashes, as seen in the 'MyProject\MyModule' example. This allows for even finer-grained organization of your code."},{"order":16,"type":"subheading","text":"The Global Namespace"},{"order":17,"type":"paragraph","text":"If a piece of code is not within any declared namespace, it resides in the global namespace. To explicitly refer to an element in the global namespace, prefix it with a backslash (e.g., '\strlen' to refer to the built-in 'strlen' function)."},{"order":18,"type":"code","text":"<?php
namespace MyProject\MyModule;

function myStringLength(string $str): int {
 return \strlen($str); // Calling the global strlen function
}
?>"},{"order":19,"type":"subheading","text":"Namespace Aliasing (use ... as ...)"},{"order":20,"type":"paragraph","text":"You can create aliases for namespaces or elements using the 'use ... as ...' syntax. This is useful for shortening long namespace names or resolving naming conflicts."},{"order":21,"type":"code","text":"<?php
use MyProject\MyModule\MyClass as ClassAlias;

$obj = new ClassAlias(); // Using the alias
?>"},{"order":22,"type":"subheading","text":"Autoloading and Namespaces"},{"order":23,"type":"paragraph","text":"Namespaces work seamlessly with autoloading. You can configure your autoloader to map namespaces to directory structures, allowing PHP to automatically load the necessary files when a class or interface is used.  PSR-4 is a widely adopted standard for autoloading based on namespaces."},{"order":24,"type":"subheading","text":"Best Practices"},{"order":25,"type":"bullet_point","text":"Use a consistent naming convention for your namespaces (e.g., 'Vendor\Package\Component')."},{"order":26,"type":"bullet_point","text":"Organize your code into logical modules and sub-modules using namespaces."},{"order":27,"type":"bullet_point","text":"Use the 'use' keyword to import namespaces and elements for better readability."},{"order":28,"type":"bullet_point","text":"Follow the PSR-4 autoloading standard for easy integration with other libraries and frameworks."},{"order":29,"type":"paragraph","text":"By using namespaces effectively, you can create more organized, maintainable, and reusable PHP code."}]
